#include "dfre/mission_event_actor_flags.hpp"
#include <iostream>
using namespace dfre;
int main(){unsigned seed;while(std::cin>>seed){MissionTickState s;for(unsigned g:{0u,1u,3u})s.tables.groups[g].resize(4);const unsigned side=std::uint32_t(std::int32_t(seed%5)-2);std::array<int,4> counts{int(seed/16%4),int(seed%4),0,int(seed/4%4)};if(seed%17==0)counts[1]=-1;unsigned damage=0xa5a5;s.globals.mission_67f528=seed%3;
 for(unsigned g:{0u,1u,3u})for(unsigned i=0;i<4;++i){auto& a=s.tables.groups[g][i];a.active=(seed+i+g)%2;a.definition_index=a.active?1:0;a.field_72=std::uint16_t((seed+i+g)%5-2);a.field_76=0x1234;a.field_110=0x500000;s.extra_for({std::uint8_t(g),i}).field_74=0x9876;}
 std::vector<unsigned> reads;std::vector<std::vector<unsigned>> writes,calls;AiActorRef last{};MissionEventActorFlagBindings b;b.current_count=[&](std::size_t g){return counts[g];};b.before_read=[&](unsigned at){reads.push_back(at);};b.before_write=[&](unsigned at,unsigned width,unsigned value){writes.push_back({at,width,value});if(width==2){for(unsigned g:{0u,1u,3u})for(unsigned i=0;i<4;++i)if(at==mission_actor_source_address(g,i)+0x74)last={std::uint8_t(g),i};if(seed&32)s.tables.groups[last.group][last.index].field_72=9;s.tables.groups[last.group][last.index].field_76=0xabcd;}else if(seed&64)s.tables.groups[last.group][last.index].field_110=0x500010;};
 const auto mutate=[&](const AiActorRef& ref){counts[ref.group]=int((seed+ref.group+ref.index)%5);if(seed&4 && ref.index+1<4)s.tables.groups[ref.group][ref.index+1].field_72=std::uint16_t(side);};
 b.update=[&](const auto& ref,unsigned callback,unsigned message){calls.push_back({callback,mission_actor_source_address(ref.group,ref.index),message,unsigned(s.extra_for(ref).field_74),damage});mutate(ref);damage=0x100+unsigned(ref.index);};
 b.remove_45da30=[&](const auto& ref){calls.push_back({0x45da30,mission_actor_source_address(ref.group,ref.index)});s.tables.groups[ref.group][ref.index]={};s.extra_for(ref)={};mutate(ref);if(seed&8)s.globals.mission_67f528=0;};b.broadcast_442630=[&](unsigned type,std::uint8_t* data,unsigned length){calls.push_back({0x442630,type,length,unsigned(data[0])|unsigned(data[1])<<8});};
 if(seed%2)mission_event_actor_remove(s,side,b);else mission_event_actor_flags(s,side,damage,b);
 std::cout<<"{\"damage\":"<<damage<<",\"host\":"<<s.globals.mission_67f528<<",\"counts\":["<<counts[0]<<','<<counts[1]<<','<<counts[3]<<"],\"rows\":[";bool comma=false;for(unsigned g:{1u,3u,0u})for(unsigned i=0;i<4;++i){if(comma)std::cout<<',';comma=true;const auto& a=s.tables.groups[g][i];std::cout<<'['<<a.field_72<<','<<s.extra_for({std::uint8_t(g),i}).field_74<<','<<a.field_76<<','<<a.field_110<<','<<unsigned(a.active)<<']';}std::cout<<"],\"reads\":[";for(std::size_t i=0;i<reads.size();++i){if(i)std::cout<<',';std::cout<<reads[i];}std::cout<<"]";const auto emit=[&](const char* name,const auto& rows){std::cout<<",\""<<name<<"\":[";for(std::size_t i=0;i<rows.size();++i){if(i)std::cout<<',';std::cout<<'[';for(std::size_t j=0;j<rows[i].size();++j){if(j)std::cout<<',';std::cout<<rows[i][j];}std::cout<<']';}std::cout<<']';};emit("writes",writes);emit("calls",calls);std::cout<<"}\n";
}}
